INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('policy_condition', 'Honest Disclosure Policy: All pre-owned units undergo a 50-point mechanical check. Existing cosmetic scratches, touch-ups, or repairs are photographed and documented upfront under \"Vehicle Condition & History\" prior to reservation.', '2026-11-26 19:24:41');
INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('policy_papers', 'Clean Papers Guarantee: Every vehicle includes verified original LTO OR/CR, HPG clearance eligibility, deed of sale, and transparent ownership history. Walk-in mechanic inspections and test drives are warmly welcomed.', '2026-11-26 19:24:41');
INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('policy_release', 'Automatic Release Policy: If payment or showroom verification is not completed before the reservation deadline, the hold automatically expires and the vehicle status immediately returns to AVAILABLE for other buyers.', '2026-11-26 19:24:41');
INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('policy_reservation', 'Customers may place a temporary reservation hold for 1, 2, 3, or up to 7 custom days. To lock the unit beyond the hold deadline, complete the refundable reservation deposit at our showroom or via verified bank transfer before the countdown expires.', '2026-11-26 19:24:41');
